// 検索用の文字列正規化。インデックス作成・クエリ処理の両方で使う。
// 全角英数字・半角カタカナを NFKC で統一するが、商品コードの区切りである
// 全角チルダ(～, U+FF5E)だけは規約により変換せず残す(docs/商品コード規約.md)。
const FULLWIDTH_TILDE = '～'
const TILDE_PLACEHOLDER = ''

export function normalize(text) {
  return text
    .toLowerCase()
    .trim()
    .replaceAll(FULLWIDTH_TILDE, TILDE_PLACEHOLDER)
    .normalize('NFKC')
    .replaceAll(TILDE_PLACEHOLDER, FULLWIDTH_TILDE)
}

